CREATE TABLE IF NOT EXISTS public.countries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  code text,
  is_active boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS countries_name_lower_idx ON public.countries ((lower(name)));
ALTER TABLE public.countries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "countries read auth" ON public.countries;
CREATE POLICY "countries read auth" ON public.countries FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "countries write admin" ON public.countries;
CREATE POLICY "countries write admin" ON public.countries FOR ALL TO authenticated USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP TRIGGER IF EXISTS trg_countries_touch ON public.countries;
CREATE TRIGGER trg_countries_touch BEFORE UPDATE ON public.countries FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE UNIQUE INDEX IF NOT EXISTS products_name_lower_idx ON public.products ((lower(name)));

